/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import cindexOfRow = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = zeros( [ 2, 2 ], {
		'dtype': 'complex64'
	});
	const x = zeros( [ 2 ], {
		'dtype': 'complex64'
	});
	const workspace = zeros( [ 2 ], {
		'dtype': 'uint8'
	});

	cindexOfRow( [ A, x, workspace ] ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not an array of ndarrays...
{
	cindexOfRow( '10' ); // $ExpectError
	cindexOfRow( 10 ); // $ExpectError
	cindexOfRow( true ); // $ExpectError
	cindexOfRow( false ); // $ExpectError
	cindexOfRow( null ); // $ExpectError
	cindexOfRow( undefined ); // $ExpectError
	cindexOfRow( [] ); // $ExpectError
	cindexOfRow( {} ); // $ExpectError
	cindexOfRow( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = zeros( [ 2, 2 ], {
		'dtype': 'complex64'
	});
	const x = zeros( [ 2 ], {
		'dtype': 'complex64'
	});
	const workspace = zeros( [ 2 ], {
		'dtype': 'uint8'
	});

	cindexOfRow(); // $ExpectError
	cindexOfRow( [ A, x, workspace ], {} ); // $ExpectError
}

